const lines = require('fs').readFileSync('analyzer/health_log.jsonl','utf8').trim().split('\n').filter(Boolean);
const entries = lines.map(l => { try{return JSON.parse(l)}catch(e){return null} }).filter(Boolean);
console.log('Total entries parsed:', entries.length);

// Simulate dashboard JS logic
function legacyScore(entry) {
  if (typeof entry.score === 'number') return entry.score;
  const flags = entry.flags || [];
  if (flags.length === 0) return 100;
  let score = 100;
  for (const f of flags) {
    const fl = f.toLowerCase();
    if (fl.includes('runaway') || fl.includes('tool calls')) score -= 30;
    else if (fl.includes('unfixed loop') || fl.includes('same error')) score -= 25;
    else if (fl.includes('written') && fl.includes('loop')) score -= 20;
    else score -= 15;
  }
  return Math.max(0, score);
}
function entryStatus(e) { return e.status || (e.flags&&e.flags.length>0?'degraded':'healthy'); }
function parseAssessment(raw) {
  if (!raw || raw === 'healthy') return {isStructured:false};
  try { const o=JSON.parse(raw); if(o&&typeof o==='object') return {isStructured:true, reason:o.reason||'', action:o.recommended_action||'', prompt:o.suggested_prompt||''}; } catch(e) {}
  const m = raw.match(/\{[\s\S]*?\}/);
  if (m) { try { const o=JSON.parse(m[0]); if(o&&typeof o==='object') return {isStructured:true, reason:o.reason||'', action:o.recommended_action||'', prompt:o.suggested_prompt||''}; } catch(e) {} }
  return {isStructured:false, text:raw};
}
entries.forEach((e,i) => {
  const s = entryStatus(e);
  const sc = legacyScore(e);
  const p = parseAssessment(e.assessment);
  console.log('Entry '+i+': status='+s+' score='+sc+' structured='+p.isStructured+' flags='+((e.flags||[]).length));
});
"
